Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define HUGE_INF 17446744073709551616ULL
#define ULL unsigned long long
using namespace std;

ULL modVal, totalN, totalK, dpTable[19][300005];
ULL factorials[300005], invFactorials[300005];

ULL fastExponent(ULL base, ULL exp) {
    ULL result = 1ULL;
    while (exp > 0) {
        if (exp & 1ULL) result = (result * base) % modVal;
        base = (base * base) % modVal;
        exp >>= 1ULL;
    }
    return result;
}

ULL nCr(int a, int b) {
    return (((factorials[a] * invFactorials[b]) % modVal) * invFactorials[a - b]) % modVal;
}

ULL compute() {
    int i, j, mask;
    factorials[0] = 1ULL;
    ULL limit = max(totalN, totalK);
    for (i = 1; i <= limit; i++) {
        factorials[i] = (factorials[i - 1] * (ULL)i) % modVal;
    }
    invFactorials[limit] = fastExponent(factorials[limit], modVal - 2ULL);
    for (i = limit - 1; i >= 0; i--) {
        invFactorials[i] = (invFactorials[i + 1] * (ULL)(i + 1)) % modVal;
    }
    for (i = 1; i <= totalN; i++) {
        dpTable[1][i] = invFactorials[i];
    }
    ULL totalAnswer = dpTable[1][totalN] * nCr(totalK, 1) % modVal;
    int maxIter = min(18, (int)totalK);
    for (i = 2; i <= maxIter; i++) {
        for (j = totalN; j > 0; j = (j - 1) & totalN) {
            if (!dpTable[i - 1][j]) continue;
            int remaining = totalN ^ j;
            for (mask = remaining; mask > j; mask = (mask - 1) & remaining) {
                dpTable[i][j ^ mask] += dpTable[i - 1][j] * invFactorials[mask];
                if (dpTable[i][j ^ mask] > HUGE_INF) dpTable[i][j ^ mask] %= modVal;
            }
        }
        for (j = totalN; j > 0; j = (j - 1) & totalN) {
            if (dpTable[i][j] >= modVal) dpTable[i][j] %= modVal;
        }
        ULL res = dpTable[i][totalN] * nCr(totalK, i) % modVal;
        res = (res * factorials[i]) % modVal;
        totalAnswer = (totalAnswer + res >= modVal ? totalAnswer + res - modVal : totalAnswer + res);
    }
    totalAnswer = (totalAnswer * factorials[totalN]) % modVal;
    return totalAnswer;
}

int main() {
    cin >> totalN >> totalK >> modVal;
    ULL answer = fastExponent(totalK, totalN);
    if (totalN % 2 == 0) answer = (answer - compute() + modVal) % modVal;
    cout << answer << endl;
    return 0;
}
</original_code>
